const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Canada';
  const aoi = ee.FeatureCollection("FAO/GAUL/2015/level0")
              .filter(ee.Filter.eq('ADM0_NAME', countryName))
              .geometry();

  const startDate2023 = '2023-01-01';
  const endDate2023 = '2023-08-03';
  const startDate2025 = '2025-01-01';
  const endDate2025 = '2025-08-03';

  const modisBurned = ee.ImageCollection('MODIS/MCD64A1/061').select('BurnDate');

  // Helper function to calculate burned area
  const getBurnedArea = (startDate, endDate) => {
    const collection = modisBurned.filterDate(startDate, endDate);
    if (collection.size().getInfo() === 0) {
      return {area: null, collectionSize: 0, pixelCount: 0};
    }

    const burnImage = collection.max().gt(0); // Create a binary image of burned pixels
    const burnAreaImage = burnImage.multiply(ee.Image.pixelArea());

    const stats = burnAreaImage.reduceRegion({
      reducer: ee.Reducer.sum().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: aoi,
      scale: 3000,
      maxPixels: 1e9
    });

    const area = stats.get('BurnDate_sum');
    const count = stats.get('BurnDate_count');

    return {
        area: area.getInfo(), 
        collectionSize: collection.size().getInfo(),
        pixelCount: count.getInfo()
    };
  };

  // 2. Data Acquisition & Processing
  const results2023 = getBurnedArea(startDate2023, endDate2023);
  const results2025 = getBurnedArea(startDate2025, endDate2025);

  // 3. Validation & Final Answer
  console.log(`2023 Img Collection Size: ${results2023.collectionSize}`);
  if (results2023.area !== null) {
      console.log(`2023 Burned Area (km2): ${(results2023.area / 1e6).toFixed(0)}`);
      console.log(`2023 Valid Pixels: ${results2023.pixelCount}`);
  }

  console.log(`2025 Img Collection Size: ${results2025.collectionSize}`);
  if (results2025.collectionSize === 0) {
      console.log("No images found for 2025 as the year is in the future.");
      console.log('C1');
      return;
  }

  if (results2023.area === null || results2025.area === null) {
      console.log("Calculation failed for one of the periods.");
      console.log('C3');
      return;
  }

  if (results2023.pixelCount === 0 || results2025.pixelCount === 0) {
      console.log("No valid pixels to compare after processing.");
      console.log('C2');
      return;
  }

  console.log(`2025 Burned Area (km2): ${(results2025.area / 1e6).toFixed(0)}`);

  if (results2025.area > results2023.area) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

